//! 🧪️ Each staged named-index alias remains in a caller-owned output slot through cancellation and complete paid close.
use super::*;
use crate::{named_edit::VecRankedKeys,retained_clone::RetainedCloneSource,allocation_testing::observe_retirement_allocations as observe};
fn grant(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn debit(bank:&mut RetainedCloneGrant,work:u64,p:RetainedCloneProgress,heap:(usize,usize),totals:&mut(usize,usize)){assert!(work<=bank.maximum_items as u64);assert!(p.fits(*bank));assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));bank.maximum_items-=work as usize;bank.maximum_copy_bytes-=p.copied_bytes;bank.maximum_capacity_bytes-=p.retained_capacity_bytes;bank.maximum_release_bytes-=p.released_bytes;totals.0+=heap.0;totals.1+=heap.1;}
fn close(index:&mut AdmittedNamedKeyIndex,bank:&mut RetainedCloneGrant,totals:&mut(usize,usize),limit:u64){index.begin_close();for _ in 0..limit{if index.terminal_is_empty(){break}let g=grant(index.close_demand(4096).unwrap());let(turn,h)=observe(||index.close_step(g));let work=turn.work;debit(bank,work,turn.result.unwrap().progress(),h,totals);}assert!(index.terminal_is_empty());let(turn,h)=observe(||index.close_step(Default::default()));assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().progress(),Default::default());assert_eq!(h,(0,0));}
#[test]
fn named_index_partial_aliases_keep_actual_work_and_one_original_bank(){
 let law:serde_json::Value=serde_json::from_str(include_str!("actual.json")).unwrap();let schema:serde_json::Value=serde_json::from_str(include_str!("actual.schema.json")).unwrap();assert_eq!(schema["properties"]["laws"]["const"],law["laws"]);let limit=law["maximumTurns"].as_u64().unwrap();
 for cut in law["projectionCuts"].as_array().unwrap(){let stock=&law["stock"];let mut bank=RetainedCloneGrant{maximum_items:stock["items"].as_u64().unwrap()as usize,maximum_copy_bytes:stock["copy"].as_u64().unwrap()as usize,maximum_capacity_bytes:stock["capacity"].as_u64().unwrap()as usize,maximum_release_bytes:stock["release"].as_u64().unwrap()as usize,maximum_depth:stock["depth"].as_u64().unwrap()as usize};let(rows,h)=observe(||law["keys"].as_array().unwrap().iter().map(|key|key.as_str().unwrap().to_owned()).collect::<Vec<_>>());let mut totals=h;let birth=RetainedCloneSource::<Vec<String>>::owned_constructor_demand::<()>();let(turn,h)=observe(||semio_framework_value_clone_source_testing::admit_owned(rows,(),grant(RetirementDemand{copy_bytes:RetainedCloneSource::<Vec<String>>::constructor_copy_bytes(),capacity_bytes:birth.capacity_bytes,depth:birth.depth,..Default::default()})));let work=turn.work;let(mut source,p)=turn.result.map_err(|(error,..)|error).unwrap();debit(&mut bank,work,p,h,&mut totals);
 let mut index={let ranked=VecRankedKeys{original:source.borrow(),key:String::as_str};let(turn,h)=observe(||NamedKeyIndexPreparation::new(ranked.len(),grant(NamedKeyIndexPreparation::constructor_demand())));let work=turn.work;let mut preparation=turn.result.unwrap().unwrap();debit(&mut bank,work,paid(NamedKeyIndexPreparation::constructor_demand()),h,&mut totals);for _ in 0..limit{if preparation.output_ready(){break}let g=grant(preparation.demand(&ranked,4096).unwrap());let(turn,h)=observe(||preparation.advance(&ranked,g));let work=turn.work;debit(&mut bank,work,turn.result.unwrap().progress(),h,&mut totals);}assert!(preparation.output_ready());let g=grant(preparation.take_demand().unwrap());let(turn,h)=observe(||preparation.take(g));let work=turn.work;let(index,p)=turn.result.unwrap().unwrap();debit(&mut bank,work,p,h,&mut totals);preparation.begin_close();assert!(preparation.terminal_is_empty());assert_eq!(observe(||drop(preparation)).1,(0,0));let keys=index.order().iter().map(|&i|source.borrow().get()[i].clone()).collect::<Vec<_>>();let mut expected=law["keys"].as_array().unwrap().iter().map(|x|x.as_str().unwrap().to_owned()).collect::<Vec<_>>();expected.sort();assert_eq!(serde_json::to_value(keys).unwrap(),serde_json::to_value(expected).unwrap());index};
 let mut output=None;{let ranked=VecRankedKeys{original:source.borrow(),key:String::as_str};let g=grant(index.project_demand(&ranked).unwrap());let(turn,h)=observe(||index.project(&ranked,&mut output,RetainedCloneGrant{maximum_items:0,..g}));assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().progress(),Default::default());assert!(output.is_none());assert_eq!(h,(0,0));for step in 0..cut.as_u64().unwrap(){let(turn,h)=observe(||index.project(&ranked,&mut output,g));let work=turn.work;assert!(work>0);debit(&mut bank,work,turn.result.unwrap().progress(),h,&mut totals);assert_eq!(output.as_ref().unwrap().ready(),step==1);}if output.as_ref().is_some_and(AdmittedNamedKeyIndex::ready){let(turn,h)=observe(||index.project(&ranked,&mut output,g));assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().progress(),Default::default());assert_eq!(h,(0,0));}}
 if let Some(alias)=output.as_mut(){close(alias,&mut bank,&mut totals,limit);}assert_eq!(observe(||drop(output)).1,(0,0));close(&mut index,&mut bank,&mut totals,limit);assert_eq!(observe(||drop(index)).1,(0,0));for _ in 0..limit{if source.terminal_is_empty(){break}let g=grant(source.next_close_demand(4096).unwrap());let(turn,h)=observe(||source.close_step(g));let work=turn.work;debit(&mut bank,work,turn.result.unwrap().progress(),h,&mut totals);}assert!(source.terminal_is_empty());assert_eq!(observe(||drop(source)).1,(0,0));assert_eq!(totals.0,totals.1);}
}
